import json
from itertools import permutations, combinations

def parse_time_24h(s):
    # Expects 'H:MM' in 24-hour format
    h, m = s.split(':')
    return int(h) * 60 + int(m)

def minutes_to_str(m):
    h = m // 60
    mm = m % 60
    return f"{h}:{mm:02d}"

def simulate_order(order, participants, travel_times, start_loc, start_time_min):
    cur_loc = start_loc
    cur_time = start_time_min
    itinerary = []
    total_travel = 0
    total_wait = 0

    for name in order:
        p = participants[name]
        travel = travel_times[cur_loc][p["location"]]
        arrival = cur_time + travel
        wait = max(0, p["start"] - arrival)
        start_meet = max(arrival, p["start"])
        end_meet = start_meet + p["min_duration"]

        if end_meet > p["end"]:
            return None  # infeasible

        itinerary.append({
            "action": "meet",
            "location": p["location"],
            "person": name,
            "start_time": minutes_to_str(start_meet),
            "end_time": minutes_to_str(end_meet),
        })
        total_travel += travel
        total_wait += wait
        cur_time = end_meet
        cur_loc = p["location"]

    return {
        "itinerary": itinerary,
        "finish_time": cur_time,
        "total_travel": total_travel,
        "total_wait": total_wait,
        "met_count": len(order)
    }

def choose_best_schedule(participants, travel_times, start_loc, start_time_min):
    names = list(participants.keys())
    best = None

    # Maximize number of friends met; ties -> earliest finish; then min wait; then min travel
    for k in range(len(names), 0, -1):
        found_any = False
        for comb in combinations(names, k):
            for perm in permutations(comb):
                res = simulate_order(perm, participants, travel_times, start_loc, start_time_min)
                if res is None:
                    continue
                found_any = True
                if best is None:
                    best = res
                else:
                    # Compare according to objective
                    if res["met_count"] > best["met_count"]:
                        best = res
                    elif res["met_count"] == best["met_count"]:
                        if res["finish_time"] < best["finish_time"]:
                            best = res
                        elif res["finish_time"] == best["finish_time"]:
                            if res["total_wait"] < best["total_wait"]:
                                best = res
                            elif res["total_wait"] == best["total_wait"]:
                                if res["total_travel"] < best["total_travel"]:
                                    best = res
        if found_any:
            # As soon as we find at least one feasible schedule for size k, no need to try smaller k
            break
    return best

def main():
    # Input variables
    travel_times = {
        "Financial District": {
            "Fisherman's Wharf": 10,
            "Pacific Heights": 13,
            "Mission District": 17
        },
        "Fisherman's Wharf": {
            "Financial District": 11,
            "Pacific Heights": 12,
            "Mission District": 22
        },
        "Pacific Heights": {
            "Financial District": 13,
            "Fisherman's Wharf": 13,
            "Mission District": 15
        },
        "Mission District": {
            "Financial District": 17,
            "Fisherman's Wharf": 22,
            "Pacific Heights": 16
        }
    }

    participants = {
        "David": {
            "location": "Fisherman's Wharf",
            "start": parse_time_24h("10:45"),
            "end": parse_time_24h("15:30"),
            "min_duration": 15
        },
        "Timothy": {
            "location": "Pacific Heights",
            "start": parse_time_24h("9:00"),
            "end": parse_time_24h("15:30"),
            "min_duration": 75
        },
        "Robert": {
            "location": "Mission District",
            "start": parse_time_24h("12:15"),
            "end": parse_time_24h("19:45"),
            "min_duration": 90
        }
    }

    start_location = "Financial District"
    start_time = parse_time_24h("9:00")

    best = choose_best_schedule(participants, travel_times, start_location, start_time)
    if best is None:
        output = {"itinerary": []}
    else:
        output = {"itinerary": best["itinerary"]}

    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
